<div class="container"><div class="page-head"><div class="kicker mb-3">SHOP / INGREDIENTES / PACKS</div><h1>Catálogo</h1><p class="text-muted">35 productos de ejemplo disponibles en inventario. Cada uno tiene imagen, descripción, origen y precio.</p></div><form class="row g-2 mb-4" method="get"><input type="hidden" name="page" value="catalogo"><div class="col-md-5"><input class="form-control" type="search" name="buscar" placeholder="Buscar productos" value="<?=h((string)($_GET['buscar']??''))?>"></div><div class="col-md-4"><select class="form-select" name="categoria"><option value="">Todas las categorías</option><?php foreach (['base'=>'Bases','sabor'=>'Sabores','suplemento'=>'Suplementos','fibra'=>'Fibras','pack'=>'Presentaciones'] as $key=>$label): ?><option value="<?=h($key)?>" <?=($_GET['categoria']??'')===$key?'selected':''?>><?=h($label)?></option><?php endforeach ?></select></div><div class="col-md-3"><button class="btn btn-brand w-100" type="submit">Filtrar</button></div></form>
<?php $params=[];$sql='SELECT * FROM productos WHERE activo=1'; $category=(string)($_GET['categoria']??''); $search=trim((string)($_GET['buscar']??'')); if(in_array($category,['base','sabor','suplemento','fibra','pack'],true)){$sql.=' AND categoria=?';$params[]=$category;} if($search!==''){$sql.=' AND (nombre LIKE ? OR descripcion LIKE ?)';$params[]="%$search%";$params[]="%$search%";} $sql.=' ORDER BY id DESC';$products=q($sql,$params)->fetchAll(); ?>
<p class="small-muted mb-3"><?=count($products)?> productos encontrados</p><div class="row row-cols-1 row-cols-sm-2 row-cols-lg-3 row-cols-xl-4 g-4"><?php foreach($products as $p): ?><div class="col"><article class="card product-card"><a href="index.php?page=detalle&id=<?=(int)$p['id']?>"><img src="<?=h(product_image($p))?>" alt="Foto de <?=h($p['nombre'])?>" class="product-image" loading="lazy"></a><div class="card-body d-flex flex-column"><div class="tag align-self-start mb-2"><?=h(ucfirst($p['categoria']))?></div><h5 class="card-title"><?=h($p['nombre'])?></h5><p class="small-muted flex-grow-1"><?=h(mb_strimwidth($p['descripcion'],0,105,'…'))?></p><div class="d-flex justify-content-between align-items-center mb-3"><strong><?=money($p['precio'])?></strong><small class="<?= $p['cantidad_almacen']>0?'text-success':'text-danger' ?>"><?= (int)$p['cantidad_almacen'] ?> en stock</small></div><form method="post" action="actions.php"><input type="hidden" name="action" value="add_cart"><?=csrf_input()?><input type="hidden" name="producto_id" value="<?=(int)$p['id']?>"><button type="submit" class="btn btn-brand w-100" <?=$p['cantidad_almacen']<1?'disabled':''?>>Añadir al carrito</button></form></div></article></div><?php endforeach ?></div><?php if(!$products): ?><div class="surface empty-state text-center">No hay productos que coincidan con tu búsqueda.</div><?php endif ?></div>
